import{_ as t}from"./chunks/pohledy.D03Xp3rL.js";import{_ as i}from"./chunks/btn_edit.Bv-WsnWb.js";import{_ as n}from"./chunks/btn_vyjadreni.Dg2MFdOG.js";import{_ as s,o as a,c as o,aa as r}from"./chunks/framework.BAs_AphD.js";const l="/buildary-help-preview/media/en/tickets/en_seznam-ukolu.png",c="/buildary-help-preview/media/en/tickets/en_filtry_mu.png",d="/buildary-help-preview/media/en/tickets/en_zahlavi_tabulky_mu.png",h="/buildary-help-preview/media/en/tickets/en_konfig_mrizky.png",g="/buildary-help-preview/media/en/tickets/en_sprava_pohledu.png",p="/buildary-help-preview/media/en/tickets/en_svisla_trojtecka.png",m="/buildary-help-preview/media/en/tickets/en_presun_sloupce.png",u="/buildary-help-preview/media/en/tickets/en_razeni.png",w="/buildary-help-preview/media/en/tickets/en_filtr_mrizky.png",f="/buildary-help-preview/media/en/tickets/en_filtr_parametru.png",k="/buildary-help-preview/media/cs/firstofall/btn_filtr.png",b="/buildary-help-preview/media/en/tickets/en_ukoly_ikony.png",y="/buildary-help-preview/media/cs/firstofall/btn_trashcan.png",_="/buildary-help-preview/media/cs/tickets/btn_popis.png",v="/buildary-help-preview/media/en/tickets/en_multiselect.png",G=JSON.parse('{"title":"Ticket List","description":"","frontmatter":{"title":"Ticket List","wiki":"en:tickets:task_grid"},"headers":[],"relativePath":"en/tickets/task_grid.md","filePath":"en/tickets/task_grid.md","lastUpdated":1794388980000}'),T={name:"en/tickets/task_grid.md"};function z(x,e,S,I,P,q){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="ticket-list" tabindex="-1">Ticket List <a class="header-anchor" href="#ticket-list" aria-label="Permalink to &quot;Ticket List&quot;">​</a></h1><figure class="shot" style="--w:620px;"><img src="'+l+'" alt="Ticket List" width="600" loading="lazy"></figure><p>The <strong>top row</strong> of the window contains <strong>filters</strong> that determine how much data is loaded from the server into the list below. Using these filters can significantly speed up loading the list, especially when hundreds or thousands of tickets have been created for a project.</p><img src="'+c+'" alt="Ticket List Filters" width="500" loading="lazy"><p><strong>You can filter by:</strong></p><ul><li><strong>search term</strong> ⇒ after entering a keyword, the following fields are searched: subject, description, statement, category, and labels. The resulting list contains all tickets where the word appears in any of the searched fields, including inflected forms. The word therefore only needs to be entered in its basic form.</li><li><strong>relationship to the ticket</strong> ⇒ selection of tickets that the user created, is assigned to, needs to approve, etc.</li><li><strong>ticket status and deadline</strong> ⇒ for example current / this week / overdue / unfinished / completed, etc.</li><li><strong>project part</strong> ⇒ if the project is divided into parts (in Project Settings → Project Parts and Drawings), tickets concerning only a selected part can be displayed.</li><li><strong>view</strong> ⇒ by default, this is set to &quot;<strong>Project</strong>&quot;, meaning tickets concerning the current project. The second option is &quot;<strong>Overview</strong>&quot;, where the list contains tickets across all current projects with the Ticket Management module enabled where the user is assigned with the appropriate permissions.</li></ul><p>Additional filters are then available in the grid (table) header. These work with the data that has already been loaded.</p><h2 id="working-with-the-grid" tabindex="-1">Working with the Grid <a class="header-anchor" href="#working-with-the-grid" aria-label="Permalink to &quot;Working with the Grid&quot;">​</a></h2><figure class="shot" style="--w:620px;"><img src="'+d+'" alt="Grid Header" width="600" loading="lazy"></figure><p>The Ticket List is displayed as a <strong>GRID</strong>. The <strong>grid is an exceptionally flexible tool</strong> that allows tickets to be sorted, filtered, and grouped in the way that best suits each user&#39;s needs. The number and selection of fields can also be customized.</p><p>Each change to the grid layout creates a new <strong>VIEW</strong>. A <strong>view can be saved and set as the default</strong> view whenever the page is opened.</p><p>Users can switch freely between saved views depending on which parameters they need to monitor at a given time.</p><h3 id="view-configuration" tabindex="-1">View Configuration <a class="header-anchor" href="#view-configuration" aria-label="Permalink to &quot;View Configuration&quot;">​</a></h3><img src="'+h+'" alt="Options for View Configuration" width="700" loading="lazy"> Each user can individually configure which parameters they want to display in the grid and how they want them displayed, creating their own system of views. This is done using three buttons located directly above the grid on the right. From left to right, they are: <p><strong>View Selection</strong></p><img src="'+t+'" alt="View Selection" width="300" loading="lazy"><p>contains all saved views, which the user can switch between as needed.</p><p>The code list contains 5 predefined views, but each user can add their own.</p><p>The selected view is set as the default and will be displayed whenever the page is opened.</p><p><strong>View Management</strong></p><img src="'+g+'" alt="View Management" width="200" loading="lazy"><p>is used to create, name, rename, or delete views, set the default view, etc.</p><p>If a user makes changes to the grid, such as adding or removing columns, moving them to a different position, etc., and wants to preserve these settings, they can name and save the view using this option.</p><p><strong>More Options = Three-Dot Menu</strong></p><img src="'+p+'" alt="More Options" width="150" loading="lazy"><p>allows the user to <strong>select</strong> exactly which <strong>columns</strong> they want to include in the view from the code list, or <strong>add a grouping panel</strong>, into which one or more parameters can then be dragged from the header.</p><h3 id="grid-configuration" tabindex="-1">Grid Configuration <a class="header-anchor" href="#grid-configuration" aria-label="Permalink to &quot;Grid Configuration&quot;">​</a></h3><p><strong>1. Grid Layout</strong></p><figure class="shot" style="--w:670px;"><img src="'+m+'" alt="Moving a Column" width="650" loading="lazy"></figure><p>The grid layout can be changed very easily. Using the left mouse button, any <strong>column can be grabbed</strong> by its gray header and <strong>moved to another position</strong> in the grid, either to the left or right, or to the grouping panel above the grid (the grouping panel must first be created using the &quot;Three-Dot Menu&quot; described above).</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Multiple criteria can be added to the grouping panel, and their order can be changed in the same way.</p></div><p>An example of a grouped layout is shown in the image on the right.</p><p><strong>2. Sorting Column Values</strong></p><figure class="shot" style="--w:400px;"><img src="'+u+'" alt="Sorting Items" width="380" loading="lazy"></figure><p>Items in columns can be <strong>sorted in ascending or descending order</strong>, including across multiple columns at the same time. In this case, the sorting priority is indicated by the order in which sorting was applied to the columns.</p><p><strong>Clicking a column name in the grid header</strong> enables ascending sorting of the values in the column, indicated by an upward-pointing arrow. <strong>Clicking again</strong> reverses the direction and applies descending sorting, with the arrow pointing downward. <strong>A third click</strong> disables sorting and the arrow disappears.</p><p>The <strong>second column</strong> can be added to the sort using <strong>Shift + left-click</strong>. To change the sorting direction, use Shift + click again. To stop sorting only this column, also use Shift + click.</p><p>The same method can be used to sort additional columns.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>To stop sorting for all columns at once, simply click the header of a column with a downward-pointing arrow. If all arrows point upward, click any of them. The arrow will change direction and all other sorting indicators will disappear. Clicking it again removes the remaining sorting as well.</p></div><p><strong>3. Grid Filters</strong></p><figure class="shot" style="--w:520px;"><img src="'+w+'" alt="Grid Filters" width="500" loading="lazy"></figure><p>A <strong>filter row</strong> is located below the gray grid header.</p><p>Different types of filters are available depending on the nature of the column. Some contain text fields for entering a search term, others provide a code list for selecting a value, while others contain a calendar for entering dates, etc.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If an orange frame appears above the grid, it indicates that a filter has been applied and the grid is displaying filtered data. Clicking the cross in this notification disables all filters on the grid.</p></div><figure class="shot" style="--w:420px;"><img src="'+f+'" alt="Parameter Filter" width="400" loading="lazy"></figure><p>Some columns contain a <strong>filter icon</strong> directly in the header <img src="'+k+'" alt="Filter Icon" data-no-zoom loading="lazy"> → in these cases, <strong>multiple values can be selected at once</strong>. The orange highlighting of the icon and the number indicating how many values have been selected for the given criterion show that this filter is active - <em>see the image on the right for the Status criterion</em>.</p><h2 id="working-with-tickets-in-the-grid" tabindex="-1">Working with Tickets in the Grid <a class="header-anchor" href="#working-with-tickets-in-the-grid" aria-label="Permalink to &quot;Working with Tickets in the Grid&quot;">​</a></h2><figure class="shot" style="--w:520px;"><img src="'+b+'" alt="Active Ticket Elements" width="500" loading="lazy"></figure><p><strong>Edit Ticket</strong> is available via the <img src="'+i+'" alt="Edit Pencil" data-no-zoom loading="lazy"> icon or by clicking the <strong>Ticket Subject</strong>. In both cases, the <strong>Ticket Details</strong> window opens, where the required changes can be made.</p><p><strong>Delete Ticket</strong> is available via the <img src="'+y+'" alt="Trash Can" data-no-zoom loading="lazy"> icon.</p><p>For <strong>each ticket, the <strong>Ticket Description</strong> and <strong>Statement</strong></strong> can be viewed without the possibility of editing them.</p><p>The <img src="'+_+'" alt="Ticket Description Icon" data-no-zoom loading="lazy"> icon expands the <strong>Ticket Description details</strong> and, if available, <strong>the latest entry in the Statement thread</strong> (see image).</p><p>The <img src="'+n+'" alt="Statement Icon" data-no-zoom loading="lazy"> icon indicates that a <strong>Statement</strong> exists for the ticket and opens the <strong>entire Statement thread</strong> with its associated records.</p><figure class="shot" style="--w:420px;"><img src="'+v+'" alt="Bulk Ticket Operations" width="400" loading="lazy"></figure><p>The application allows users to select tickets and then perform <strong>bulk operations</strong>, such as <strong>deleting tickets</strong> or <strong>exporting</strong> the selected tickets.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Selecting the checkbox in the grid header selects all tickets at once. You can then deselect the checkboxes for tickets that should not be included in the selection. In many cases, this can be the faster approach.</p></div>',57)])])}const A=s(T,[["render",z]]);export{G as __pageData,A as default};
